-- Additive installer platform. Legacy accounts and referrals remain unverified/review.
CREATE TABLE installer_auth_user (id TEXT PRIMARY KEY NOT NULL,name TEXT NOT NULL,email TEXT NOT NULL UNIQUE,emailVerified INTEGER NOT NULL,image TEXT,createdAt INTEGER NOT NULL,updatedAt INTEGER NOT NULL);
CREATE TABLE installer_auth_session (id TEXT PRIMARY KEY NOT NULL,expiresAt INTEGER NOT NULL,token TEXT NOT NULL UNIQUE,createdAt INTEGER NOT NULL,updatedAt INTEGER NOT NULL,ipAddress TEXT,userAgent TEXT,userId TEXT NOT NULL REFERENCES installer_auth_user(id) ON DELETE CASCADE);
CREATE INDEX installer_auth_session_user_idx ON installer_auth_session(userId);
CREATE TABLE installer_auth_account (id TEXT PRIMARY KEY NOT NULL,accountId TEXT NOT NULL,providerId TEXT NOT NULL,userId TEXT NOT NULL REFERENCES installer_auth_user(id) ON DELETE CASCADE,accessToken TEXT,refreshToken TEXT,idToken TEXT,accessTokenExpiresAt INTEGER,refreshTokenExpiresAt INTEGER,scope TEXT,password TEXT,createdAt INTEGER NOT NULL,updatedAt INTEGER NOT NULL);
CREATE INDEX installer_auth_account_user_idx ON installer_auth_account(userId);
CREATE UNIQUE INDEX installer_auth_account_provider_idx ON installer_auth_account(providerId,accountId);
CREATE TABLE installer_auth_verification (id TEXT PRIMARY KEY NOT NULL,identifier TEXT NOT NULL,value TEXT NOT NULL,expiresAt INTEGER NOT NULL,createdAt INTEGER NOT NULL,updatedAt INTEGER NOT NULL);
CREATE INDEX installer_auth_verification_identifier_idx ON installer_auth_verification(identifier);
CREATE TABLE installer_auth_rate_limit (id TEXT PRIMARY KEY NOT NULL,key TEXT NOT NULL UNIQUE,count INTEGER NOT NULL,lastRequest INTEGER NOT NULL);
CREATE TABLE installer_phone_challenges (id TEXT PRIMARY KEY,phone_hash TEXT NOT NULL,phone_e164 TEXT NOT NULL,code_hash TEXT NOT NULL,session_hash TEXT NOT NULL,created_at TEXT NOT NULL,expires_at TEXT NOT NULL,resend_after TEXT NOT NULL,mode TEXT NOT NULL,send_state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,verified_at TEXT,proof_hash TEXT,consumed_at TEXT);
CREATE INDEX installer_phone_challenges_phone ON installer_phone_challenges(phone_hash,resend_after);
CREATE TABLE installer_test_messages(id TEXT PRIMARY KEY,channel TEXT NOT NULL,recipient TEXT NOT NULL,body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE installer_platform_settings(id INTEGER PRIMARY KEY CHECK(id=1),config_json TEXT NOT NULL CHECK(json_valid(config_json)),version INTEGER NOT NULL,updated_at TEXT NOT NULL,updated_by TEXT NOT NULL);
INSERT INTO installer_platform_settings VALUES(1,'{}',1,strftime('%Y-%m-%dT%H:%M:%fZ','now'),'migration');
CREATE TABLE installer_settings_revisions(id TEXT PRIMARY KEY,config_json TEXT NOT NULL CHECK(json_valid(config_json)),actor TEXT NOT NULL,created_at TEXT NOT NULL);
ALTER TABLE solar_company_partners ADD COLUMN approval_status TEXT NOT NULL DEFAULT 'pending';
ALTER TABLE solar_company_partners ADD COLUMN paused INTEGER NOT NULL DEFAULT 1 CHECK(paused IN(0,1));
ALTER TABLE solar_company_partners ADD COLUMN daily_limit INTEGER NOT NULL DEFAULT 3 CHECK(daily_limit BETWEEN 0 AND 100000);
ALTER TABLE solar_company_partners ADD COLUMN supported_products_json TEXT NOT NULL DEFAULT '["shared_residential"]' CHECK(json_valid(supported_products_json));
ALTER TABLE solar_company_partners ADD COLUMN preferences_json TEXT NOT NULL DEFAULT '{}' CHECK(json_valid(preferences_json));
ALTER TABLE solar_company_partners ADD COLUMN rotation_sequence INTEGER NOT NULL DEFAULT 0;
ALTER TABLE solar_company_partners ADD COLUMN line_user_id TEXT;
ALTER TABLE solar_company_partners ADD COLUMN terms_version TEXT;
ALTER TABLE solar_company_partners ADD COLUMN terms_accepted_at TEXT;
ALTER TABLE solar_company_partners ADD COLUMN portal_contact_name TEXT NOT NULL DEFAULT '';
ALTER TABLE solar_company_partners ADD COLUMN portal_phone TEXT NOT NULL DEFAULT '';
ALTER TABLE solar_company_partners ADD COLUMN trial_granted_at TEXT;
CREATE TABLE installer_memberships(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES solar_company_partners(id),user_id TEXT NOT NULL UNIQUE REFERENCES installer_auth_user(id),role TEXT NOT NULL CHECK(role IN('owner','member')));
CREATE TABLE installer_credit_accounts(company_id TEXT PRIMARY KEY REFERENCES solar_company_partners(id),available INTEGER NOT NULL DEFAULT 0 CHECK(available>=0),reserved INTEGER NOT NULL DEFAULT 0 CHECK(reserved>=0),trial_remaining INTEGER NOT NULL DEFAULT 0 CHECK(trial_remaining>=0),debt INTEGER NOT NULL DEFAULT 0 CHECK(debt>=0));
CREATE TABLE installer_credit_ledger(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES installer_credit_accounts(company_id),kind TEXT NOT NULL,available_delta INTEGER NOT NULL DEFAULT 0,reserved_delta INTEGER NOT NULL DEFAULT 0,trial_delta INTEGER NOT NULL DEFAULT 0,debt_delta INTEGER NOT NULL DEFAULT 0,source_id TEXT,idempotency_key TEXT NOT NULL UNIQUE,reason TEXT NOT NULL,actor TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX installer_credit_ledger_company ON installer_credit_ledger(company_id,created_at);
CREATE TRIGGER installer_ledger_check BEFORE INSERT ON installer_credit_ledger BEGIN
 SELECT CASE WHEN typeof(NEW.available_delta)<>'integer' OR typeof(NEW.reserved_delta)<>'integer' OR typeof(NEW.trial_delta)<>'integer' OR typeof(NEW.debt_delta)<>'integer' THEN RAISE(ABORT,'credits must be integers') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM installer_credit_accounts WHERE company_id=NEW.company_id AND available+NEW.available_delta>=0 AND reserved+NEW.reserved_delta>=0 AND trial_remaining+NEW.trial_delta>=0 AND debt+NEW.debt_delta>=0) THEN RAISE(ABORT,'insufficient credit balance') END;
END;
CREATE TRIGGER installer_ledger_apply AFTER INSERT ON installer_credit_ledger BEGIN
 UPDATE installer_credit_accounts SET available=available+NEW.available_delta,reserved=reserved+NEW.reserved_delta,trial_remaining=trial_remaining+NEW.trial_delta,debt=debt+NEW.debt_delta WHERE company_id=NEW.company_id;
END;
CREATE TRIGGER installer_ledger_no_update BEFORE UPDATE ON installer_credit_ledger BEGIN SELECT RAISE(ABORT,'ledger is immutable'); END;
CREATE TRIGGER installer_ledger_no_delete BEFORE DELETE ON installer_credit_ledger BEGIN SELECT RAISE(ABORT,'ledger is immutable'); END;
CREATE TABLE installer_trial_grants(company_id TEXT PRIMARY KEY REFERENCES solar_company_partners(id),created_at TEXT NOT NULL,actor TEXT NOT NULL);
CREATE TABLE installer_enquiries(id TEXT PRIMARY KEY,canonical_key TEXT NOT NULL UNIQUE,lead_id TEXT NOT NULL REFERENCES leads(id),created_at TEXT NOT NULL,request_expires_at TEXT NOT NULL,verification_state TEXT NOT NULL,qualification_state TEXT NOT NULL,duplicate_state TEXT NOT NULL,status TEXT NOT NULL,product TEXT NOT NULL CHECK(product IN('shared_residential','exclusive_residential')),recipient_limit INTEGER NOT NULL CHECK(recipient_limit BETWEEN 1 AND 3 AND (product<>'exclusive_residential' OR recipient_limit=1)),rule_version TEXT NOT NULL,suppressed_at TEXT,suppression_reason TEXT);
CREATE INDEX installer_enquiries_queue ON installer_enquiries(status,created_at);
CREATE TABLE installer_enquiry_leads(lead_id TEXT PRIMARY KEY REFERENCES leads(id),enquiry_id TEXT NOT NULL REFERENCES installer_enquiries(id),created_at TEXT NOT NULL);
INSERT INTO installer_enquiries SELECT 'legacy-'||id,'legacy-'||id,id,created_at,COALESCE(distribution_expires_at,created_at),'unverified','review','legacy','review','shared_residential',3,rule_version_id,suppressed_at,suppression_reason FROM leads;
INSERT INTO installer_enquiry_leads SELECT lead_id,id,created_at FROM installer_enquiries;
ALTER TABLE lead_recipient_deliveries ADD COLUMN enquiry_id TEXT REFERENCES installer_enquiries(id);
ALTER TABLE lead_recipient_deliveries ADD COLUMN product TEXT NOT NULL DEFAULT 'shared_residential';
ALTER TABLE lead_recipient_deliveries ADD COLUMN credit_cost INTEGER NOT NULL DEFAULT 0 CHECK(credit_cost>=0);
ALTER TABLE lead_recipient_deliveries ADD COLUMN price_minor INTEGER NOT NULL DEFAULT 0 CHECK(price_minor>=0);
ALTER TABLE lead_recipient_deliveries ADD COLUMN funding_source TEXT NOT NULL DEFAULT 'legacy' CHECK(funding_source IN('legacy','trial','purchased'));
ALTER TABLE lead_recipient_deliveries ADD COLUMN available_at TEXT;
ALTER TABLE lead_recipient_deliveries ADD COLUMN claim_deadline TEXT;
ALTER TABLE lead_recipient_deliveries ADD COLUMN notification_status TEXT NOT NULL DEFAULT 'pending';
ALTER TABLE lead_recipient_deliveries ADD COLUMN viewed_at TEXT;
ALTER TABLE lead_recipient_deliveries ADD COLUMN delivery_channel TEXT NOT NULL DEFAULT 'legacy' CHECK(delivery_channel IN('legacy','portal'));
UPDATE lead_recipient_deliveries SET enquiry_id='legacy-'||lead_id;
CREATE UNIQUE INDEX installer_delivery_company_once ON lead_recipient_deliveries(enquiry_id,partner_id);
CREATE TABLE installer_payment_orders(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES solar_company_partners(id),package_id TEXT NOT NULL,credits INTEGER NOT NULL CHECK(credits>0),amount_minor INTEGER NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('pending','authorizing','reconciliation-required','paid','failed','cancelled','refunded','reversed')),provider TEXT NOT NULL,provider_order_id TEXT UNIQUE,receipt_reference TEXT,refunded_minor INTEGER NOT NULL DEFAULT 0 CHECK(refunded_minor>=0),reversed_credits INTEGER NOT NULL DEFAULT 0 CHECK(reversed_credits>=0),authorization_nonce TEXT,credited_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE installer_payment_events(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES installer_payment_orders(id),provider_event_id TEXT NOT NULL UNIQUE,status TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE installer_claims(id TEXT PRIMARY KEY,delivery_id TEXT NOT NULL UNIQUE REFERENCES lead_recipient_deliveries(id),company_id TEXT NOT NULL REFERENCES solar_company_partners(id),reason TEXT NOT NULL,notes TEXT NOT NULL,status TEXT NOT NULL,decision_notes TEXT,submitted_at TEXT NOT NULL,resolved_at TEXT,resolved_by TEXT);
CREATE TABLE installer_outbox(id TEXT PRIMARY KEY,delivery_id TEXT REFERENCES lead_recipient_deliveries(id),enquiry_id TEXT REFERENCES installer_enquiries(id),company_id TEXT REFERENCES solar_company_partners(id),kind TEXT NOT NULL,state TEXT NOT NULL,attempts INTEGER NOT NULL DEFAULT 0,next_attempt_at TEXT NOT NULL,lease_until TEXT,provider_reference TEXT,last_error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(delivery_id,kind));
CREATE INDEX installer_outbox_due ON installer_outbox(state,next_attempt_at);
CREATE UNIQUE INDEX installer_company_line_unique ON solar_company_partners(line_user_id) WHERE line_user_id IS NOT NULL;
CREATE TABLE installer_share_tokens(id TEXT PRIMARY KEY,delivery_id TEXT NOT NULL REFERENCES lead_recipient_deliveries(id),token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,revoked_at TEXT,created_at TEXT NOT NULL,created_by TEXT NOT NULL);
CREATE TABLE installer_line_links(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES solar_company_partners(id),nonce_hash TEXT NOT NULL UNIQUE,line_user_id TEXT,expires_at TEXT NOT NULL,consumed_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE installer_line_invitations(id TEXT PRIMARY KEY,line_user_id TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,consumed_at TEXT,created_at TEXT NOT NULL);
CREATE INDEX installer_line_invitation_user ON installer_line_invitations(line_user_id,created_at);
CREATE TABLE installer_webhook_events(id TEXT PRIMARY KEY,provider TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE installer_operational_events(id TEXT PRIMARY KEY,event_type TEXT NOT NULL,enquiry_id TEXT,delivery_id TEXT,company_id TEXT,amount_minor INTEGER,attribution_json TEXT CHECK(attribution_json IS NULL OR json_valid(attribution_json)),created_at TEXT NOT NULL);
CREATE TRIGGER installer_enquiry_product_lock BEFORE UPDATE OF product,recipient_limit ON installer_enquiries WHEN EXISTS(SELECT 1 FROM lead_recipient_deliveries WHERE enquiry_id=OLD.id) BEGIN SELECT RAISE(ABORT,'distributed product and recipient limit are immutable'); END;
CREATE TRIGGER installer_delivery_facts_lock BEFORE UPDATE OF enquiry_id,partner_id,lead_id,product,credit_cost,price_minor,funding_source,available_at,claim_deadline ON lead_recipient_deliveries WHEN OLD.delivery_channel='portal' BEGIN SELECT RAISE(ABORT,'delivery facts are immutable'); END;
CREATE TRIGGER installer_delivery_no_delete BEFORE DELETE ON lead_recipient_deliveries WHEN OLD.delivery_channel='portal' BEGIN SELECT RAISE(ABORT,'portal delivery history is immutable'); END;
CREATE TRIGGER installer_delivery_guard BEFORE INSERT ON lead_recipient_deliveries WHEN NEW.delivery_channel='portal' BEGIN
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM leads l JOIN solar_company_partners p ON p.id=NEW.partner_id JOIN installer_platform_settings s ON s.id=1 WHERE l.id=NEW.lead_id AND l.quality_score>=COALESCE(json_extract(s.config_json,'$.minimumQuality'),4) AND (COALESCE(json_extract(s.config_json,'$.ownerRequired'),1)=0 OR l.ownership_status='owner') AND l.air_conditioner_count>=COALESCE(json_extract(s.config_json,'$.minimumAcUnits'),4) AND l.quality_score>=COALESCE(json_extract(p.accepted_lead_criteria_json,'$.minimumQuality'),1) AND (COALESCE(json_extract(p.accepted_lead_criteria_json,'$.ownerRequired'),0)=0 OR l.ownership_status='owner') AND l.air_conditioner_count>=COALESCE(json_extract(p.accepted_lead_criteria_json,'$.minimumAcUnits'),0) AND l.monthly_bill_thb>=COALESCE(json_extract(p.preferences_json,'$.minimumBill'),0) AND (json_extract(p.preferences_json,'$.propertyTypes') IS NULL OR EXISTS(SELECT 1 FROM json_each(p.preferences_json,'$.propertyTypes') WHERE value=l.property_type)) AND l.adult_confirmed_at IS NOT NULL AND l.privacy_notice_version_id=NEW.privacy_notice_version_id AND l.consent_version=NEW.consent_version AND json(NEW.fields_disclosed_json)=json(l.disclosed_fields_snapshot_json)) THEN RAISE(ABORT,'qualification or consent snapshot mismatch') END;
 SELECT CASE WHEN NEW.enquiry_id IS NULL OR NEW.available_at IS NULL OR NEW.claim_deadline IS NULL OR NEW.delivered_at<>NEW.available_at THEN RAISE(ABORT,'missing portal delivery facts') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM installer_platform_settings WHERE id=1 AND json_extract(config_json,'$.collectionEnabled')=1 AND COALESCE(json_extract(config_json,'$.deliveryPaused'),1)=0 AND CAST(strftime('%H','now','+7 hours') AS INTEGER)>=COALESCE(json_extract(config_json,'$.startHour'),9) AND CAST(strftime('%H','now','+7 hours') AS INTEGER)<COALESCE(json_extract(config_json,'$.endHour'),17)) THEN RAISE(ABORT,'allocation disabled or outside delivery hours') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM installer_enquiries e JOIN leads l ON l.id=e.lead_id WHERE e.id=NEW.enquiry_id AND e.lead_id=NEW.lead_id AND e.product=NEW.product AND e.verification_state='verified' AND e.qualification_state='eligible' AND e.duplicate_state IN('original','repeat') AND e.status IN('queued','partially-delivered','unmatched') AND e.suppressed_at IS NULL AND julianday(e.request_expires_at)>julianday('now') AND l.suppressed=0 AND l.consent_withdrawn_at IS NULL AND l.deleted_at IS NULL AND l.archived_at IS NULL AND l.distribution_allowed=1 AND l.quote_contact_requested=1 AND l.third_party_disclosure_authorized_v2=1 AND l.consent_scope_v2='shared_residential_solar_referral' AND julianday(l.distribution_expires_at)>julianday('now')) THEN RAISE(ABORT,'enquiry is not eligible') END;
 SELECT CASE WHEN NEW.product<>'shared_residential' THEN RAISE(ABORT,'exclusive delivery disabled') END;
 SELECT CASE WHEN (SELECT COUNT(DISTINCT partner_id) FROM lead_recipient_deliveries WHERE enquiry_id=NEW.enquiry_id)>=(SELECT MIN(3,recipient_limit) FROM installer_enquiries WHERE id=NEW.enquiry_id) THEN RAISE(ABORT,'recipient limit reached') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM solar_company_partners p JOIN leads l ON l.id=NEW.lead_id JOIN installer_platform_settings s ON s.id=1 WHERE p.id=NEW.partner_id AND p.approval_status='approved' AND p.active=1 AND p.paused=0 AND p.contract_state='active' AND p.archived_at IS NULL AND (p.contract_effective_date IS NULL OR date(p.contract_effective_date)<=date('now','+7 hours')) AND (p.contract_expiry_date IS NULL OR date(p.contract_expiry_date)>=date('now','+7 hours')) AND p.terms_version=json_extract(s.config_json,'$.termsVersion') AND p.terms_accepted_at IS NOT NULL AND EXISTS(SELECT 1 FROM json_each(p.supported_products_json) WHERE value=NEW.product) AND (EXISTS(SELECT 1 FROM json_each(p.service_provinces_json) WHERE value=l.province) OR EXISTS(SELECT 1 FROM json_each(p.service_areas_json) WHERE value=l.province)) AND (SELECT COUNT(*) FROM lead_recipient_deliveries d WHERE d.partner_id=p.id AND d.delivery_channel='portal' AND date(d.available_at,'+7 hours')=date('now','+7 hours'))<p.daily_limit AND (p.operational_capacity IS NULL OR (SELECT COUNT(*) FROM lead_recipient_deliveries d WHERE d.partner_id=p.id AND d.delivery_channel='portal' AND date(d.available_at,'+7 hours')=date('now','+7 hours'))<p.operational_capacity)) THEN RAISE(ABORT,'company is not eligible') END;
 SELECT CASE WHEN NEW.credit_cost<>(SELECT COALESCE(json_extract(config_json,'$.sharedCredits'),2) FROM installer_platform_settings WHERE id=1) OR NEW.price_minor<>(SELECT COALESCE(json_extract(config_json,'$.sharedCredits'),2)*COALESCE(json_extract(config_json,'$.creditValueMinor'),20000) FROM installer_platform_settings WHERE id=1) THEN RAISE(ABORT,'incorrect price snapshot') END;
 SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM installer_credit_accounts WHERE company_id=NEW.partner_id AND debt=0 AND ((NEW.funding_source='trial' AND trial_remaining>=1) OR (NEW.funding_source='purchased' AND available>=NEW.credit_cost))) THEN RAISE(ABORT,'no funding available') END;
END;
CREATE TRIGGER installer_delivery_commit AFTER INSERT ON lead_recipient_deliveries WHEN NEW.delivery_channel='portal' BEGIN
 INSERT INTO installer_credit_ledger(id,company_id,kind,available_delta,trial_delta,source_id,idempotency_key,reason,actor,created_at) VALUES('delivery-'||NEW.id,NEW.partner_id,'delivery', CASE WHEN NEW.funding_source='purchased' THEN -NEW.credit_cost ELSE 0 END , CASE WHEN NEW.funding_source='trial' THEN -1 ELSE 0 END ,NEW.id,'delivery:'||NEW.id,'Portal enquiry available',NEW.delivered_by,NEW.available_at);
 UPDATE solar_company_partners SET rotation_sequence=(SELECT COALESCE(MAX(rotation_sequence),0)+1 FROM solar_company_partners) WHERE id=NEW.partner_id;
 INSERT INTO installer_outbox(id,delivery_id,enquiry_id,company_id,kind,state,next_attempt_at,created_at,updated_at) VALUES('notify-'||NEW.id,NEW.id,NEW.enquiry_id,NEW.partner_id,'installer-delivery','pending',NEW.available_at,NEW.available_at,NEW.available_at);
 INSERT INTO installer_outbox(id,delivery_id,enquiry_id,company_id,kind,state,next_attempt_at,created_at,updated_at) VALUES('homeowner-'||NEW.id,NEW.id,NEW.enquiry_id,NEW.partner_id,'homeowner-confirmation','pending',NEW.available_at,NEW.available_at,NEW.available_at);
 UPDATE installer_enquiries SET status= CASE WHEN (SELECT COUNT(DISTINCT partner_id) FROM lead_recipient_deliveries WHERE enquiry_id=NEW.enquiry_id)>=recipient_limit THEN 'delivered' ELSE 'partially-delivered' END WHERE id=NEW.enquiry_id;
END;
